// Exercise template deduction by passing concrete, non-overloaded function pointers.
// We use captureless lambdas converted to function pointers via unary + to avoid
// defining global functions while ensuring an unambiguous pointer type.
// No inputs/outputs are required; the function returns a lightweight value we discard.
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
  using Ret = uint64_t;
  Ret (*fp)() = +[]() -> Ret { return 42u; };
  auto cache = hwy::DeduceFunctionCache(fp);
  (void)cache;  // ensure instantiation and call without relying on the value
} else if (choice == 1) {
  using Ret = int;
  using A0 = int;
  Ret (*fp)(A0) = +[](A0 a0) -> Ret { return a0; };
  auto cache = hwy::DeduceFunctionCache(fp);
  (void)cache;
} else {
  using Ret = hwy::FuncOutput;
  using A0 = const void*;
  using A1 = hwy::FuncInput;
  Ret (*fp)(A0, A1) = +[](A0, A1 n) -> Ret { return static_cast<Ret>(n); };
  auto cache = hwy::DeduceFunctionCache(fp);
  (void)cache;
}
// Requirements enforced:
// - Argument is an explicit function pointer (non-overloaded, unique type).
// - Multiple signatures improve coverage of template deduction paths.
// Validation: Stub compiles without extra dependencies, avoids ambiguity, and does
// not assume any specific FunctionCache members; no persistent objects to output.

// Create a few valid TypeInfo combinations and exercise formatting into a 100-byte buffer.
// Requirements enforced: string100 capacity >= 100, sensible non-negative N.
{
  char out[100];

  // Choose a vector length N in a reasonable range.
  size_t N = (size_t)(*FUZZ_PARAM(unsigned int) % 65); // 0..64

  // Exercise several common scalar types to maximize coverage.
  hwy::detail::TypeInfo ti_u8   {1, /*is_float=*/false, /*is_signed=*/false, /*is_bf16=*/false};
  hwy::detail::TypeInfo ti_i8   {1, false, true,  false};
  hwy::detail::TypeInfo ti_u16  {2, false, false, false};
  hwy::detail::TypeInfo ti_i16  {2, false, true,  false};
  hwy::detail::TypeInfo ti_bf16 {2, true,  false, true }; // represent bfloat16
  hwy::detail::TypeInfo ti_f32  {4, true,  false, false};
  hwy::detail::TypeInfo ti_f64  {8, true,  false, false};
  hwy::detail::TypeInfo ti_i32  {4, false, true,  false};

  // Call the target with different type infos.
  hwy::detail::TypeName(ti_u8,  N, out);
  hwy::detail::TypeName(ti_i8,  N, out);
  hwy::detail::TypeName(ti_u16, N, out);
  hwy::detail::TypeName(ti_i16, N, out);
  hwy::detail::TypeName(ti_bf16,N, out);
  hwy::detail::TypeName(ti_f32, N, out);
  hwy::detail::TypeName(ti_f64, N, out);
  hwy::detail::TypeName(ti_i32, N, out);
  // No outputs to return; buffer is local and overwritten each call.
}
// Validation: Ensures buffer is sized to 100 bytes and N is non-negative; uses plausible TypeInfo combinations.

