// Call the monotonic wall clock. No inputs or persistent objects required.
const double now = hwy::platform::Now();
// Property: result should be finite and non-negative in typical steady clocks.
// We only assert finiteness to be portable across platform epochs.
FUZZ_ASSERT(now == now, "Now() must be a finite number");
// Validation: Stub calls Now() once and asserts a finite result. No objects to manage.

// Provide a writable buffer of at least 100 bytes as required.
char cpu100[100];
cpu100[0] = '\0';
const bool ok = hwy::platform::HaveTimerStop(cpu100);
// If not supported, buffer will contain a descriptive CPU string; we do not
// depend on its contents here, only ensure call safety.
if (!ok) {
  // Per API, callers should not use timer::Stop if this is false; bail to avoid UB.
  FUZZ_BAIL();
}
// Validation: Ensures buffer size >=100 and bails if Stop is unsafe, honoring API contract.

// Potentially expensive; call once and sanity-check the return.
const double hz = hwy::platform::InvariantTicksPerSecond();
// Expect a positive frequency.
FUZZ_ASSERT(hz > 0.0, "InvariantTicksPerSecond must be positive");
// Validation: Calls once, asserts positive frequency. No object lifetimes involved.

// Potentially expensive; call once.
const uint64_t res = hwy::platform::TimerResolution();
// Resolution (overhead) can be zero on some platforms but must be finite.
// No strict assertion beyond reading the value.
(void)res;
// Validation: Invokes API and accepts any returned tick delta; no objects involved.

