// t0 must be a valid Timestamp captured from the same clock.
// Compute elapsed seconds since t0.
const double dt = hwy::SecondsSince(*t0);
// Elapsed since a recent timestamp should be non-negative and finite.
FUZZ_ASSERT(dt == dt && dt >= 0.0, "SecondsSince must be finite and non-negative");
// Return t0 to the pool as it remains valid.
// Validation: Uses provided Timestamp by const ref, asserts sane elapsed, and preserves input.

// Obtain a fenced pre-region absolute tick value. No inputs required.
const hwy::timer::Ticks t0 = hwy::timer::Start();
// Follow-up Start to compute a small elapsed delta (valid even if Stop is unsafe).
const hwy::timer::Ticks t1 = hwy::timer::Start();
volatile hwy::timer::Ticks elapsed = t1 - t0;  // unsigned wrap-safe
(void)elapsed;
